"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["87157"],{8456(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.organizacao.unidade.superior_forma_ciclo","status":422,"titulo":"A unidade superior informada formaria ciclo na hierarquia"},"descricao":{"codigo":"uniplus.organizacao.unidade.superior_forma_ciclo","requisitos":["UNI-REQ-0008"],"oQueAconteceu":["A unidade superior informada **formaria um ciclo** na hierarquia \u2014 s\xf3\\nacontece na atualiza\xe7\xe3o, nunca na cria\xe7\xe3o, j\xe1 que uma unidade rec\xe9m-criada\\nainda n\xe3o tem subordinadas capazes de fechar um ciclo.","Dois casos caem nesta causa:","1. **Auto-refer\xeancia** \u2014 a unidade foi declarada como superior de si\\n   mesma.\\n2. **Ciclo indireto** \u2014 a unidade superior informada \xe9, ela pr\xf3pria, uma\\n   descendente (direta ou indireta) da unidade que est\xe1 sendo editada. Se\\n   isso fosse aceito, a \xe1rvore deixaria de ser \xe1rvore: subir na hierarquia\\n   a partir dali levaria de volta ao ponto de partida, sem nunca chegar \xe0\\n   reitoria."],"comoResolver":["Escolha uma unidade superior que n\xe3o seja a pr\xf3pria unidade nem uma de\\nsuas subordinadas, diretas ou indiretas. Se a inten\xe7\xe3o \xe9 reorganizar a\\nhierarquia de forma mais ampla (mover um ramo inteiro para outro lugar da\\n\xe1rvore), pode ser necess\xe1rio reordenar as edi\xe7\xf5es em v\xe1rios passos, come\xe7ando\\npelas unidades mais distantes do ciclo."],"ondeAparece":["Atualiza\xe7\xe3o de unidade"]},"modulo":{"id":"organizacao","nome":"Organiza\xe7\xe3o institucional","assunto":"Unidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);